  "apitokens.title": "API tokens",
  "apitokens.intro": "An API token is how a machine signs in: a worker on another host, a CI job, an MCP adapter, a Prometheus scraper. Its scope bounds what it reaches and its lifetime for how long. A token never carries the admin role.",
  "apitokens.denied": "Only an account with the admin role manages API tokens.",
  "apitokens.new.title": "New token",
  "apitokens.new.name": "Name",
  "apitokens.new.namePlaceholder": "e.g. worker on host-b",
  "apitokens.new.nameHint": "What it is for and which machine holds it – so you still recognise the token a year from now.",
  "apitokens.new.nameRequired": "Give the token a name.",
  "apitokens.new.scope": "Scope",
  "apitokens.new.scopeChoose": "– choose a scope –",
  "apitokens.new.scopeHint": "What the token reaches. Choose the narrowest scope that does the machine's job.",
  "apitokens.new.scopeRequired": "Choose a scope.",
  "apitokens.new.days": "Lifetime in days",
  "apitokens.new.daysHint": "Default 365, at most {max} days (5 years). 0 means it never expires.",
  "apitokens.new.daysRange": "The lifetime must be a whole number of days between 0 and {max}.",
  "apitokens.new.neverWarn": "This token never expires. It stays valid until somebody revokes it – even after the machine is long gone or the secret has been left lying somewhere. Choose this only when an expiry is genuinely impossible for this machine.",
  "apitokens.new.neverConfirm": "Yes, this token is never to expire.",
  "apitokens.new.neverRequired": "Confirm that the token is never to expire, or give it a lifetime.",
  "apitokens.new.submit": "Create token",
  "apitokens.scope.metrics": "Only GET /metrics. The narrowest scope there is, for a Prometheus scraper.",
  "apitokens.scope.status": "Only GET /api/v1/node, this server's descriptor – for another Atlas that wants to know whom it is talking to.",
  "apitokens.scope.diagrams": "Read-only: the deployed processes, a definition's model and its runtime counts, and a release's architecture sketch as everybody may see it – for a system that shows them elsewhere, such as a wiki. It cannot deploy, start or read instances, a Worker's configuration or a person.",
  "apitokens.scope.worker": "Only what “atlas worker” does: lease jobs, settle each one either way, and post a preview mail back to the outbox. The right scope for a worker in another network zone.",
  "apitokens.scope.events": "Only GET /api/v1/events, the event feed: how actions ended and which rights were granted and revoked. For a CMDB or a billing system; the token carries the feedreader role and no other.",
  "apitokens.scope.landscape": "Only the derived landscape – the mesh, its ArchiMate projection and the descriptor – for another Atlas asking for that picture. It must name the applications it may see.",
  "apitokens.scope.directory": "Only the two directory-synchronisation routes, for the scheduled process that mirrors accounts from the directory. It cannot deploy.",
  "apitokens.scope.inventory": "Only the commissioning load of a target system's holdings and the reconciliation run, for the process that reads who holds what there.",
  "apitokens.scope.full": "Everything a signed-in person without admin reaches – for a CI job, an MCP adapter or the shop's system processes, whose calls cannot be listed in advance. Broad by design; user management, secrets and backups stay refused, and it does not read the event feed.",
  "apitokens.reach.projects": "Applications the token may see (required)",
  "apitokens.reach.projectsHint": "A landscape token sees only what belongs to these applications.",
  "apitokens.reach.catalogues": "Catalogues (optional)",
  "apitokens.reach.cataloguesHint": "With none chosen the token reads the whole feed; with some, only the events about products those catalogues maintain. You can choose only catalogues you maintain.",
  "apitokens.reach.loading": "loading …",
  "apitokens.reach.none": "None found.",
  "apitokens.reach.loadFailed": "Could not be loaded: {error}",
  "apitokens.reach.required": "A landscape token needs at least one application.",
  "apitokens.vault.check": "Seal it in the vault directly",
  "apitokens.vault.name": "Vault secret name",
  "apitokens.vault.hint": "The secret then never leaves the server: it is not shown, but stored in the vault under this name. The shop's system processes sign in with the secret atlas and need the full scope for it, which carries the operator role.",
  "apitokens.vault.replaces": "A secret “{name}” already exists. It will be replaced; revoke the token it held until now afterwards.",
  "apitokens.vault.atlasNeedsFull": "The shop's system processes use the secret atlas to call the order routes, and only the full scope reaches those.",
  "apitokens.vault.unavailable": "This server has no vault (started with --vault=false), so it cannot keep a secret itself; the secret is shown once the token is created.",
  "apitokens.vault.nameRequired": "Name the vault secret.",
  "apitokens.roles.title": "Roles the token will carry",
  "apitokens.roles.choose": "Choose a scope first.",
  "apitokens.roles.minter": "A token carries the roles of the person who creates it, without admin – for an administrator, modeler, operator and user.",
  "apitokens.roles.fixed": "A {scope} token always carries exactly this role, whoever creates it.",
  "apitokens.secret.title": "The secret of “{name}”",
  "apitokens.secret.once": "Copy it now. It will never be shown again: atlas stores only its fingerprint. If it is lost, revoke the token and create a new one.",
  "apitokens.secret.use": "The machine sends it as a bearer token in the Authorization header; “atlas worker” and “atlas mcp” take it with --token or from ATLAS_TOKEN.",
  "apitokens.secret.copy": "Copy",
  "apitokens.secret.copied": "Copied",
  "apitokens.secret.copyFailed": "Could not copy – select the secret and copy it by hand.",
  "apitokens.secret.done": "Done – hide the secret",
  "apitokens.sealed": "Token “{name}” created and stored in the vault as “{secret}”. The secret has not left the server.",
  "apitokens.sealed.done": "Done",
  "apitokens.created": "Token created",
  "apitokens.createdSealed": "Token created and stored in the vault",
  "apitokens.list.title": "Tokens",
  "apitokens.list.intro": "An expired token stays listed so you can see what needs reissuing; it is no longer accepted. Revoking deletes it.",
  "apitokens.list.empty": "No tokens yet.",
  "apitokens.col.name": "Name",
  "apitokens.col.scope": "Scope",
  "apitokens.col.roles": "Roles",
  "apitokens.col.reach": "Reach",
  "apitokens.col.expires": "Expires",
  "apitokens.col.origin": "Origin",
  "apitokens.expires.never": "never expires",
  "apitokens.expires.expired": "expired",
