  "storage.alert.warn.title": "Disk space is running low",
  "storage.alert.warn.text": "{available} is left under the data directory. Once less than the reserve of {reserve} is free, Atlas takes no new writes.",
  "storage.alert.warn.forecast": "At the current consumption the reserve is reached in about {when}.",
  "storage.alert.frozen.title": "Atlas takes no new writes",
  "storage.alert.frozen.text": "Only {available} is left under the data directory, less than the reserve of {reserve}. New instances, deployments and changes are refused with 507 and nothing is changed: the caller keeps its data and can try again later. Jobs already leased may report their results, and reading goes on.",
  "storage.alert.frozen.hint": "Free space or grow the volume. Once {resume} is free, Atlas takes writes again by itself; no restart is needed.",
  "storage.alert.halted.title": "The engine has halted",
  "storage.alert.halted.text": "A write to disk failed. So that nothing acknowledged is lost and nothing refused runs later after all, the engine processes nothing more. Reading goes on.",
  "storage.alert.halted.hint": "Free space if the disk is full, then restart the server. The restart recovers exactly what was acknowledged.",
