  "storage.reclaim.title": "Giving space back",
  "storage.reclaim.noCheckpoints": "Checkpoints are switched off (--checkpoint-interval=0). Without a checkpoint the WAL cannot be compacted.",
  "storage.reclaim.on": "The WAL is compacted on every checkpoint (every {every}). It keeps only what came after the last checkpoint and what a consumer still needs.",
