  // Approvals (ADR-0475 §9).
  "approvals.title": "Approvals",
  "approvals.intro": "Answer the approvals a policy asks for before a particular action, such as deleting a document in SharePoint. An approval covers exactly the action shown; if anything about it changes, it does not count.",
  "approvals.after": "Your answer does not run the action. The policy reads the answers when the action is next tried; when that is, the process decides.",
  "approvals.signIn": "Approvals are answered by people who sign in. Sign-in is off on this server, so there is nothing to answer here.",
  "approvals.denied": "Approvals are answered by people in their own session. This sign-in has no list.",
  "approvals.truncated": "More approvals are open than one page holds. These are the {n} that expire first.",
  "approvals.waiting.title": "Waiting for your answer",
  "approvals.waiting.intro": "You are in the group that may approve these actions.",
  "approvals.waiting.empty": "No approval is waiting for your answer.",
  "approvals.answered.title": "Answered by you",
  "approvals.answered.intro": "While an approval is open you can withdraw your answer and give a new one.",
  "approvals.answered.empty": "You have not answered an open approval.",
  "approvals.onBehalf.title": "Asked on your behalf",
  "approvals.onBehalf.intro": "These actions would run in your name. Only somebody else can approve them.",
