  "security.title": "Security",
  "security.intro": "Which Workers act as whom, and by which policy. atlas decides every governed action before it runs and records the decision in the log.",
  "security.denied": "This page is for administrators.",
  "security.link.title": "Account linking (Microsoft)",
  "security.link.intro": "For people to link their Microsoft account and let Workers act in their name, atlas needs an app registration in Microsoft Entra. Without one nobody can link an account, and the account menu shows “Connected accounts” only where something is linked already.",
  "security.link.status.off": "not set up",
  "security.link.status.console": "set up",
  "security.link.status.flags": "set up by start flags",
  "security.link.status.flagsIncomplete": "start flags incomplete",
  "security.link.status.unavailable": "unavailable",
  "security.link.unavailable": "Account linking needs the vault, which is switched off on this server.",
  "security.link.flags": "This server's start flags set account linking (--link-microsoft-…). It can only be viewed here; change it there — or here, once the start flags are removed.",
  "security.link.flagsIncompleteHint": "Something is missing, so linking is off: the tenant ID, the client ID and the scopes are required.",
  "security.link.steps": "At Microsoft (Entra admin center → App registrations):",
  "security.link.step1": "Create a new registration: supported account types “Accounts in this organizational directory only”, platform “Web”, and the address below as redirect URI.",
  "security.link.step2": "Under “API permissions”, add the delegated permissions the Workers need — for SharePoint Sites.ReadWrite.All or, narrower, Sites.Selected — and grant admin consent where the tenant requires it.",
  "security.link.step3": "Under “Certificates & secrets”, create a client secret and copy its value; Entra shows it only once.",
  "security.link.step4": "Enter the directory (tenant) ID, the application (client) ID, the permissions and the secret here and save. From then on, people can link their account.",
  "security.link.redirect": "Redirect URI",
  "security.link.copy": "Copy",
  "security.link.copied": "Copied",
  "security.link.copyFailed": "Could not copy — select the address and copy it yourself.",
  "security.link.redirectDerived": "atlas derives this address from the current request. If the server is reached from outside under another address, --external-url has to be set, or it will not match the registration.",
  "security.link.tenant": "Directory (tenant) ID",
  "security.link.client": "Application (client) ID",
  "security.link.scopes": "Delegated permissions (scopes)",
  "security.link.scopesHint": "Separate scopes with spaces; atlas adds openid, profile and offline_access itself.",
  "security.link.secret": "Client secret (value)",
  "security.link.secretKept": "stored — leave empty to keep it",
  "security.link.secretSet": "set",
  "security.link.secretUnset": "not set",
  "security.link.secretHint": "The secret is kept encrypted in the vault and never shown again; no Worker and no secrets route can reach it.",
  "security.link.save": "Save",
  "security.link.saved": "Saved — people can link their account now",
  "security.link.remove": "Remove setup",
  "security.link.removed": "Removed — nobody can link an account any more",
  "security.link.removeConfirm": "Remove account linking?\n\nAfterwards nobody can link an account.",
  "security.link.removeConfirmConnections": "Remove account linking?\n\nAfterwards nobody can link an account. The existing connections ({n}) stay, but cannot act until linking is set up again for their tenant.",
  "security.link.changeConfirm": "Change the tenant or the client ID?\n\nThere are {n} connections. With another app registration their owners have to sign in again; in another tenant they cannot act any more.",
  "security.link.stranded": "{n} connections cannot act at the moment: they belong to a tenant linking is not set up for. Their owners or an administrator can revoke them.",
  "security.readiness.title": "Readiness",
  "security.readiness.intro": "Every configured Worker: whether its actions are governed, how, and where its credential is. Change a Worker's setting here.",
