  "events.title": "Events",
  "events.intro": "Two lists. The first is what atlas itself emits: its contract, checked against its code. The second is what the models of this installation throw, send and receive: read from the deployed definitions, so it promises nothing and shows what is wrong. A signal or message a model of yours throws is in the second list, never in the first.",
  "events.loading": "Loading…",
  "events.catalog.title": "Events atlas emits",
  "events.catalog.intro": "The signals and messages of atlas's system processes, the CloudEvents feed, and the log lines that belong to them. Each entry says what has happened when it is emitted, what it carries — personal data marked — and who may receive it. A model listens with a signal start or catch on the name; a system beyond atlas reads the feed. A row opens its detail.",
  "events.col.event": "Event",
  "events.col.kind": "Kind",
  "events.col.channels": "Channels",
