  "events.stability.experimental": "experimental",
  "events.since.unreleased": "Unreleased",
  "events.channel.signal.what": "a BPMN signal inside the engine: zero to many listeners, not buffered",
  "events.channel.message.what": "a BPMN message inside the engine, correlated to one receiver",
  "events.channel.feed.what": "the CloudEvents feed at /api/v1/events and its push delivery: durable, ordered, at least once",
  "events.channel.log.what": "a structured log line, named in the log catalogue",
  "events.shape": "shape",
  "events.shape.title": "A shape: the product's author names each one",
