  // The decision editor (dmn-editor.js).
  "dmn.view.overview": "Overview (DRG)",
  "dmn.view.decision": "Decision",
  "dmn.hint.tail": "<b>Save</b> keeps a draft only you see; <b>Save to model</b> writes the decision every process resolves, and is what the next Publish ships; <b>Deploy</b> ships this decision to the engine on its own, as a new version. <b>Test</b> runs it against sample inputs and shows which rules fired — nothing is saved or deployed by asking.",
  "dmn.hint.drd": "Draw the decision requirements graph. An <b>Input Data</b> node is something this model is given, a <b>Decision</b> holds logic, and a <b>Knowledge Model</b> is a reusable function a decision can invoke. Open a decision's own tab to model its logic.",
  "dmn.hint.literal": "This decision's logic is one FEEL expression: what it evaluates to is the decision's result, under the variable named below it. Its inputs are whatever the requirements graph gives it — both are adopted into a business rule task that calls this decision.",
  "dmn.hint.boxed": "A <b>knowledge model</b> is a reusable FEEL function, not a decision: nothing calls it from a process. <b>F</b> is the expression language, the list beside it is the parameters a caller passes, the body is evaluated with them, and <b>Result</b> names the variable a decision binds when it invokes this model.",
  "dmn.hint.table": "Model the decision table. <b>Input Data</b> nodes become the decision's inputs and the output column becomes its result variable — both are adopted into a business rule task that calls this decision.",
  "dmn.column.added": "“{input}” added as an input column of “{decision}”.",
  "dmn.column.removeAsk.one": "Remove the input column as well?",
  "dmn.column.removeAsk.other": "Remove the input columns as well?",
  "dmn.column.removeLine": "  • “{name}” in “{decision}”",
  "dmn.column.removeLineCount": " ({n} columns)",
  "dmn.column.removeWhy.one": "Nothing gives the decision that name any more, so this column reads a name that does not resolve and the model will not deploy.\n\nRemoving it also removes its cell in every rule, and those cells are logic somebody wrote — which is why this is a question and not something that just happens. Cancel keeps it; the findings below the canvas will point at it.",
  "dmn.column.removeWhy.other": "Nothing gives the decision those names any more, so these columns read names that do not resolve and the model will not deploy.\n\nRemoving a column also removes its cell in every rule, and those cells are logic somebody wrote — which is why this is a question and not something that just happens. Cancel keeps them; the findings below the canvas will point at each one.",
  "dmn.column.removed.one": "{n} input column removed with the {with} — Ctrl+Z takes it back.",
  "dmn.column.removed.other": "{n} input columns removed with the {with} — Ctrl+Z takes them back.",
  "dmn.column.withRequirement.one": "requirement",
  "dmn.column.withRequirement.other": "requirements",
  "dmn.draw.noView": "This view cannot draw the requirement.",
  "dmn.draw.notOnGraph": "One of the two elements is not on the requirements graph, so the requirement cannot be drawn here.",
  "dmn.draw.refused": "dmn-js will not connect these two, so this has to be drawn by hand.",
  "dmn.draw.failed": "Could not draw the requirement: {error}",
  "dmn.draw.done": "Knowledge requirement drawn — Ctrl+Z takes it back, or the bin in its context pad.",
  "dmn.addColumn.noView": "This view cannot add the column.",
  "dmn.addColumn.notOnGraph": "One of the two elements is not on the requirements graph.",
  "dmn.addColumn.noTable": "There is no decision table to add a column to.",
  "dmn.addColumn.done": "Input column “{name}” added — Ctrl+Z takes it back.",
  "dmn.addInput.noView": "This view cannot add an input.",
  "dmn.addInput.notOnGraph": "That decision is not on the requirements graph.",
  "dmn.addInput.failed": "Could not create the input: {error}",
