  "pnl.feel.sql.desc": "Run one query or statement against a {name} database on a worker",
  "pnl.feel.sql.connectorHint": "The configured {name} Worker this statement runs on, by the name it has under Workers in the Console. Its connection string is sealed into the vault there, or read by a worker you run yourself from its own environment (ATLAS_{env}_<NAME>_DSN) — either way the engine never holds a database credential (ADR-0173). With the Databases mockup switched on (Console › Workers, or ATLAS_{env}_MOCK on a worker you run yourself) the same task is answered from prepared answers in that worker's memory instead, so the model can be tried without a database (ADR-0221).",
