  "wt.Server URL": "Server URL",
  "wt.ldap://host:389 for a plain connection, ldaps://host:636 for TLS. May be a FEEL expression (fx).": "ldap://host:389 for a plain connection, ldaps://host:636 for TLS. May be a FEEL expression (fx).",
  "wt.The account the worker binds as. Empty binds anonymously.": "The account the worker binds as. Empty binds anonymously.",
  "wt.Bind password reference": "Bind password reference",
  "wt.The password lives on the server as ATLAS_CONNECTOR_<REF>_TOKEN; the model stores only this reference, never the password itself.": "The password lives on the server as ATLAS_CONNECTOR_<REF>_TOKEN; the model stores only this reference, never the password itself.",
  "wt.Client certificate reference": "Client certificate reference",
  "wt.Optional. Names a server-side secret holding one PEM bundle — certificate and private key together — presented to the directory. With no bind DN the certificate is the identity and the worker binds SASL EXTERNAL; with one it is transport only.": "Optional. Names a server-side secret holding one PEM bundle — certificate and private key together — presented to the directory. With no bind DN the certificate is the identity and the worker binds SASL EXTERNAL; with one it is transport only.",
  "wt.Yes — upgrade the connection": "Yes — upgrade the connection",
  "wt.Upgrades a plain ldap:// connection after connecting. Unnecessary for ldaps://, which is already TLS.": "Upgrades a plain ldap:// connection after connecting. Unnecessary for ldaps://, which is already TLS.",
