  "wt.The entry the operation acts on. May be a FEEL expression (fx).": "The entry the operation acts on. May be a FEEL expression (fx).",
  "wt.Attributes variable": "Attributes variable",
  "wt.A process variable holding a JSON object of attribute names to values. Modify replaces each named attribute wholesale; add/delete values change individual values, which is what a multi-valued attribute two processes both write needs — adding one group member is not a statement about everyone else's.": "A process variable holding a JSON object of attribute names to values. Modify replaces each named attribute wholesale; add/delete values change individual values, which is what a multi-valued attribute two processes both write needs — adding one group member is not a statement about everyone else's.",
  "wt.New password": "New password",
  "wt.Usually a FEEL reference to a variable, so no password is written into the model.": "Usually a FEEL reference to a variable, so no password is written into the model.",
  "wt.Page size": "Page size",
  "wt.Fetches the search in pages (RFC 2696), so a directory's administrative size limit does not refuse it. Empty uses 500; 0 asks for one unpaged search.": "Fetches the search in pages (RFC 2696), so a directory's administrative size limit does not refuse it. Empty uses 500; 0 asks for one unpaged search.",
  "wt.Maximum entries": "Maximum entries",
  "wt.Caps what may land in the result variable. A search returning more fails the job rather than truncating, because a short result set is a wrong answer, not a partial one. Empty uses 1000; 0 is unbounded.": "Caps what may land in the result variable. A search returning more fails the job rather than truncating, because a short result set is a wrong answer, not a partial one. Empty uses 1000; 0 is unbounded.",
  "wt.A search writes the matched entries as a JSON array into this variable (leave empty to discard it).": "A search writes the matched entries as a JSON array into this variable (leave empty to discard it).",
  "wt.SOAP / Web Services": "SOAP / Web Services",
  "wt.Invoke a SOAP operation on a legacy web service (WSDL)": "Invoke a SOAP operation on a legacy web service (WSDL)",
  "wt.Web service": "Web service",
  "wt.Endpoint URL": "Endpoint URL",
  "wt.The web service's endpoint (the WSDL's soap:address). May be a FEEL expression (fx).": "The web service's endpoint (the WSDL's soap:address). May be a FEEL expression (fx).",
  "wt.The operation name, used in diagnostics and as the default SOAPAction.": "The operation name, used in diagnostics and as the default SOAPAction.",
  "wt.The SOAPAction header (SOAP 1.1) or Content-Type action (1.2). Empty uses the operation name. May be a FEEL expression (fx).": "The SOAPAction header (SOAP 1.1) or Content-Type action (1.2). Empty uses the operation name. May be a FEEL expression (fx).",
  "wt.SOAP version": "SOAP version",
  "wt.1.1 (default)": "1.1 (default)",
  "wt.1.1 sends text/xml with a SOAPAction header; 1.2 sends application/soap+xml.": "1.1 sends text/xml with a SOAPAction header; 1.2 sends application/soap+xml.",
  "wt.Request body (XML)": "Request body (XML)",
  "wt.The operation's request element, placed inside the SOAP envelope's Body. Use the fx toggle for a FEEL expression that interpolates the instance's variables into the XML.": "The operation's request element, placed inside the SOAP envelope's Body. Use the fx toggle for a FEEL expression that interpolates the instance's variables into the XML.",
  "wt.The parsed SOAP response body is written into this process variable (leave empty to discard it).": "The parsed SOAP response body is written into this process variable (leave empty to discard it).",
  "wt.Create a user, set a password, enable/disable an account, or manage group membership in AD": "Create a user, set a password, enable/disable an account, or manage group membership in AD",
  "wt.ldaps://host:636 — a password set requires an encrypted channel. May be a FEEL expression (fx).": "ldaps://host:636 — a password set requires an encrypted channel. May be a FEEL expression (fx).",
