  "wt.The configured mail Worker this task sends through or whose mailbox it works with, by the name it has under Workers in the Console. Its host, credentials and default sender live on the server, never in the model. Reading or changing a mailbox needs access to that Worker: a deploy by somebody it is not shared with is refused.": "The configured mail Worker this task sends through or whose mailbox it works with, by the name it has under Workers in the Console. Its host, credentials and default sender live on the server, never in the model. Reading or changing a mailbox needs access to that Worker: a deploy by somebody it is not shared with is refused.",
