  "wt.Who receives the forwarded message, attachments included. Comma-separated; a person or group this server knows may be named by reference. Forwarding writes from the mailbox, so a deploy needs editor access to the Worker.": "Who receives the forwarded message, attachments included. Comma-separated; a person or group this server knows may be named by reference. Forwarding writes from the mailbox, so a deploy needs editor access to the Worker.",
  "wt.Comma-separated recipients. A value may be a FEEL expression (fx).": "Comma-separated recipients. A value may be a FEEL expression (fx).",
