  "pnl.ops.contacts.query.find": "An e-mail address or a phone number, compared exactly (an address ignoring case, a number by its digits) — or, with a custom field named below, that field's value. Find reads the address book itself, so a contact created a minute ago is found. Usually a FEEL expression (fx), e.g. =anfrage.absender.",
