  "pnl.ops.googlecontacts.maxHint.search": "How many matches the result holds, as Google ranks them; at most {max}. A search answers with its best matches, so more of them are simply not returned. Empty uses {default}.",
  "pnl.ops.googlecontacts.result.get": "The contact as one object: id, displayName, givenName, familyName, email, emails, phone, phones, organization, jobTitle, department, address, addresses, birthday, notes, fields (the custom fields by name) and groups (the labels). A key the contact has no value for is null, a list empty.",
  "pnl.ops.googlecontacts.result.directory": "A list of people from the directory, in the contact's shape; their id is a profile, not a contact, so it cannot be updated or labelled.",
  "pnl.ops.googlecontacts.result.saved": "The contact as Google holds it afterwards, with its id — keep it to address the contact later. Leave empty to discard it.",
