  "pnl.ops.carddav.result.get": "The contact as one object: id, displayName, givenName, familyName, email, emails, phone, phones, organization, jobTitle, department, address, addresses, birthday, notes, fields (the card's X- properties by name) and groups. A key the contact has no value for is null, a list empty — the same shape as a Google Contacts contact.",
