  // The BPMN properties panel: where a Worker Type runs, the send and shop tasks, mappings, agent tools, loops, the repair form and message fields (editor.js).
  "pnl.task.where.inEngine": "in&#8209;engine",
  "pnl.task.where.onWorker": "on a worker",
  "pnl.task.where.workerOnly": "worker only",
  "pnl.task.where.engineTitle": "This server runs this kind in its own process, so the call's latency and failures are the engine's. It can be moved onto a worker (ADR-0164).",
  "pnl.task.where.engineOnlyTitle": "This server runs this kind in its own process. It has no out-of-process form, so there is no worker to move it to.",
  "pnl.task.where.workerTitle": "This server does not run this kind itself: its jobs are leased by a worker process, so a slow call cannot stall the engine (ADR-0168).",
  "pnl.task.where.workerOnlyTitle": "This kind has no in-engine form — its work always runs on a worker (ADR-0173).",
  "pnl.task.place.lead.engine": "Atlas runs this <b>in its own process</b> on this server, so its latency and its failures are the engine&rsquo;s.",
  "pnl.task.place.lead.engineOnly": "Atlas runs this <b>in its own process</b>, and it has no out-of-process form.",
  "pnl.task.place.lead.worker": "This server does <b>not</b> run this itself: its jobs are leased by a <b>worker</b>, so a slow call cannot stall the engine.",
  "pnl.task.place.lead.workerOnly": "This has <b>no in-engine form</b>: its jobs always run on a worker.",
  "pnl.task.place.workerType.engine": "New models should prefer a <b>Job worker</b> and an <code>atlas worker</code> serving that job type; these kinds keep working and are being moved out of the engine.",
  "pnl.task.place.workerType.engineOnly": "Its work changes this server&rsquo;s own state rather than calling anything out, so there is nothing to move onto a worker.",
  "pnl.task.place.workerType.worker": "Its jobs wait for a worker process serving this job type — atlas supervises one for the kinds it offloads by default. That process holds the configured Worker&rsquo;s endpoint and credential, so the credential lives where it is used; <b>Workers</b> in the Console shows which names are served and which are configured nowhere (ADR-0168).",
  "pnl.task.place.workerType.workerOnly": "The worker process holds the connection and its credential &mdash; the model names the Worker and nothing else (ADR-0168).",
  "pnl.task.place.script.engine": "A script that hangs holds the loop with it. Atlas normally runs script tasks on a worker it starts and supervises itself; <code>--in-process-connectors</code> is what turns that off (ADR-0047).",
  "pnl.task.place.script.worker": "Atlas supervises a script worker of its own by default. The language&rsquo;s interpreter has to be installed where that worker runs, which need not be this server (ADR-0047).",
  "pnl.task.place.dmn.engine": "The engine&rsquo;s embedded DMN library evaluates it here. A decision table is computation rather than a network call, so what moving it out buys is CPU time, not protection from a slow endpoint.",
  "pnl.task.place.dmn.worker": "Its jobs wait for a worker serving the decision job type. <b>Workers</b> in the Console shows whether one is running (ADR-0157).",
  "pnl.task.place.temis.engine": "A temis evaluation is a network call this server makes itself, so its latency is the engine&rsquo;s — the case ADR-0164 is about. Moving it onto a worker also moves the service&rsquo;s endpoint and credential there (ADR-0168).",
  "pnl.task.place.temis.worker": "Its jobs wait for a worker serving this job type, and that worker holds the temis endpoint and its credential. <b>Workers</b> in the Console shows whether one is running (ADR-0157/0168).",
  "pnl.task.setup": "Setup",
  "pnl.task.setupTitle": "What this Worker Type needs before a task of it runs",
  "wt.Publish a BPMN message; a waiting receive task or message catch with a matching key continues": "Publish a BPMN message; a waiting receive task or message catch with a matching key continues",
  "wt.Reports how a product action ended, or asks a held position for one (ADR-0429).": "Reports how a product action ended, or asks a held position for one (ADR-0429).",
  "wt.Completed — the action did what was asked": "Completed — the action did what was asked",
  "wt.Rejected — it was refused, e.g. by an approver": "Rejected — it was refused, e.g. by an approver",
  "wt.Failed — it was attempted and did not succeed": "Failed — it was attempted and did not succeed",
  "wt.Outcome — report how the action ended": "Outcome — report how the action ended",
  "wt.On reaching this send task the server records how the action this instance is carrying out ended, for the order, position and command the instance holds (orderId, positionId, commandId), and the token continues. It names no Worker and carries no credential.": "On reaching this send task the server records how the action this instance is carrying out ended, for the order, position and command the instance holds (orderId, positionId, commandId), and the token continues. It names no Worker and carries no credential.",
  "wt.Action": "Action",
  "wt.The key of the product action this branch answers, as the catalogue declares it on the product whose process this is.": "The key of the product action this branch answers, as the catalogue declares it on the product whose process this is.",
  "wt.Outcome": "Outcome",
  "wt.Model one shop send task for each way the action can end, on the branch that ends it that way.": "Model one shop send task for each way the action can end, on the branch that ends it that way.",
  "wt.Command — ask a held position for an action": "Command — ask a held position for an action",
  "wt.On reaching this send task the process asks a held position of the product for an operator or system action, or its return, in the name of this process's application. The product must name that application among those it is commanded by; the provision, and an action only a customer may ask for, are refused when the task runs. It names no Worker and carries no credential.": "On reaching this send task the process asks a held position of the product for an operator or system action, or its return, in the name of this process's application. The product must name that application among those it is commanded by; the provision, and an action only a customer may ask for, are refused when the task runs. It names no Worker and carries no credential.",
  "wt.Product": "Product",
  "wt.The catalogue product whose held position is asked, by its id.": "The catalogue product whose held position is asked, by its id.",
  "wt.The key of the action to ask for, as the product declares it.": "The key of the action to ask for, as the product declares it.",
  "wt.Order": "Order",
  "wt.The order that holds the position: a literal id, or a FEEL expression (fx) over the instance's variables.": "The order that holds the position: a literal id, or a FEEL expression (fx) over the instance's variables.",
  "wt.The position on that order, likewise a literal or a FEEL expression (fx).": "The position on that order, likewise a literal or a FEEL expression (fx).",
  "wt.Receives the id of the command the action runs under. Leave empty to discard it.": "Receives the id of the command the action runs under. Leave empty to discard it.",
  "pnl.task.shop.keyProblem": "Not an action key: a key is lower-case letters, digits and dashes, 1 to 64 characters (password-reset), so no product can declare this one.",
  "pnl.task.shop.mode": "Mode",
  "pnl.task.send.search": "Search type… (e.g. message, shop, mail)",
  "pnl.task.send.messageHint": "On reaching this send task the message is published; any instance waiting on it (a receive task or message catch) with a matching correlation key continues. The token then flows straight on.",
  "pnl.task.dmnIn.targetTitle": "Decision input name (from the decision)",
  "pnl.task.dmnIn.sourceTitle": "A known variable, or any FEEL expression over the instance's variables",
  "pnl.task.io.inputMapping": "Input mapping",
