  "pnl.task.io.inputHint": "Each mapping computes a variable the activity sees (its <b>local scope</b>) from a FEEL expression over the enclosing variables. Locals shadow inherited values and are dropped when the activity completes.",
  "pnl.task.io.outputHint": "Each mapping promotes a value to the <b>process scope</b> from a FEEL expression over the activity's local scope (e.g. its result). With no output mapping the task's result merges into the process scope as-is.",
  "pnl.task.io.add": "Add mapping",
