  "pnl.task.agent.deleteParam": "Delete parameter",
  "pnl.task.agent.nameTitle": "The variable this argument is written into, in the activity's own scope",
  "pnl.task.agent.type": "Type",
  "pnl.task.agent.description": "Description",
  "pnl.task.agent.required": "Required",
  "pnl.task.agent.params": "Parameters",
  "pnl.task.agent.addParam": "Add parameter",
  "pnl.task.agent.paramsHint": "What the agent has to supply when it calls this tool. Each one is written into this activity's <b>own scope</b> under its name, so the activity reads it like any other variable. Describe each parameter: the description is what stops the model guessing a value.",
  "pnl.task.agent.notTool": "A sequence flow leads to this activity, so it is a later step of whichever tool starts that chain — not a tool the agent can call. Only the activities no flow leads to are offered to the model. Disconnect it to make it one.",
  "pnl.task.agent.callable": "The agent driving <b>{container}</b> may call this activity. It is offered under its own id — <code>{id}</code> — and its <b>Documentation</b> (General) is what the model reads to decide whether this is the tool for the job. Write when to use it, when not to, and what it returns.",
  "pnl.task.agent.thisSubprocess": "this subprocess",
  "pnl.task.agent.undocumented": "This tool has no documentation, so the agent is told that it exists and not what it is for — it will call it on the strength of its id alone. Deploy warns about this (<code>agent.tool</code>); it does not refuse it.",
  "pnl.task.repair.form": "Form",
  "pnl.task.repair.none": "— none —",
  "pnl.task.repair.hint": "Shown to an operator when this task parks behind an incident, so they can correct the values that matter instead of editing the whole variable set as JSON. Only the form's own fields are written, and the change is audited like any other. Leave it unset and the raw editor is the only way — which is fine for a task with nothing specific to say. <b>＋ New form</b> creates one; coming back to the draft links it to this task.",
  "pnl.task.loop.mode": "Mode",
  "pnl.task.loop.none": "None — runs once",
  "pnl.task.loop.loop": "Loop — repeat while a condition holds",
  "pnl.task.loop.parallel": "Multi-instance parallel — all iterations at once",
  "pnl.task.loop.sequential": "Multi-instance sequential — one after another",
  "pnl.task.loop.iterateOver": "Iterate over",
  "pnl.task.loop.collection": "A collection",
  "pnl.task.loop.fixedCount": "A fixed count",
  "pnl.task.loop.inputCollection": "Input collection (FEEL)",
  "pnl.task.loop.inputElement": "Input element",
  "pnl.task.loop.cardinality": "Loop cardinality (FEEL or a number)",
  "pnl.task.loop.outputCollection": "Output collection",
  "pnl.task.loop.outputElement": "Output element (FEEL)",
  "pnl.task.loop.completion": "Completion condition (FEEL)",
  "pnl.task.loop.hint.sequential": "Runs one iteration at a time — the next starts only when the previous finishes.",
  "pnl.task.loop.hint.parallel": "Starts every iteration at once and waits until all finish.",
  "pnl.task.loop.hint.collection": "One iteration per element of the <b>input collection</b>; the <b>input element</b> is the variable each iteration binds its item to (plus the built-in <code>loopCounter</code>).",
  "pnl.task.loop.hint.cardinality": "Runs <b>loop cardinality</b> times, each with a <code>loopCounter</code>.",
  "pnl.task.loop.hint.tail": "An <b>output collection</b> gathers each iteration's <b>output element</b> into a list in order; a <b>completion condition</b> ends the loop early.",
  "pnl.task.loop.repeatWhile": "Repeat while (FEEL)",
  "pnl.task.loop.check": "Check the condition",
  "pnl.task.loop.after": "After each run — the activity always runs at least once",
  "pnl.task.loop.before": "Before each run — the activity may be skipped entirely",
  "pnl.task.loop.max": "Max iterations",
  "pnl.task.loop.noLimit": "no limit",
  "pnl.task.loop.standardHint": "Runs the activity again and again while <b>repeat while</b> holds — one run at a time, each with a 1-based <code>loopCounter</code> the condition can read. What a run writes stays visible to the next run and to the rest of the process, so the loop can work towards its own exit. <b>Max iterations</b> is a hard stop; give a condition, a cap, or both. Without a cap the engine stops a loop after <b>1000</b> runs with an incident you can resolve to grant 1000 more — a backstop for a condition that never turns false, not a limit on a cap you set yourself.",
  "pnl.task.msg.name": "Message name",
  "pnl.task.msg.corrKey": "Correlation key (FEEL)",
  "pnl.task.msg.shared": "Shared with every event that uses this message — a throw and a catch correlate when they use the same message and their keys evaluate equal.",
