  "pnl.event.msg.add": "＋ Add message",
  "pnl.event.msg.about": "A message links a <b>throw</b> event to the <b>catch</b> events waiting for it. They correlate when they share a message and their correlation keys evaluate equal.",
  "pnl.event.timer.duration": "Duration",
  "pnl.event.timer.durationNoun": "duration",
  "pnl.event.timer.durationFeel": "a <b>duration</b> in days and time (not months or years, whose length depends on the calendar) or its ISO-8601 text — e.g. <b>= wartezeit</b> or <b>= duration(\"P\" + string(tage) + \"D\")</b>",
  "pnl.event.timer.date": "Date & time",
  "pnl.event.timer.dateNoun": "date & time",
  "pnl.event.timer.dateFeel": "a <b>date and time</b> (or a date, read as its midnight) or its RFC 3339 text — e.g. <b>= frist</b> or <b>= date and time(termin)</b>",
  "pnl.event.timer.cycle": "Cycle",
  "pnl.event.timer.cycleNoun": "cycle",
  "pnl.event.timer.cycleFeel": "the text of a repeating interval or a cron expression — e.g. <b>= \"R/PT\" + string(stunden) + \"H\"</b>",
  "pnl.event.timer.type": "Type",
  "pnl.event.timer.feelConstant": "Switch on <b>fx</b> for a FEEL expression. A timer start has no instance yet, so the expression may read <b>no variables</b>; the deploy evaluates it once and refuses one that does not yield a valid {what}.",
  "pnl.event.timer.feelInstance": "Switch on <b>fx</b> for a FEEL expression, evaluated when the timer is armed against the instance's variables. It must yield {feel}. If it yields neither, no timer is set: an incident is raised on the event, and resolving it once the data is fixed arms the timer again.",
  "pnl.event.sig.name": "Signal name",
  "pnl.event.sig.shared": "Shared with every event that uses this signal — a broadcast reaches every catch, boundary, event subprocess, and start event of the same name.",
  "pnl.event.sig.label": "Signal",
  "pnl.event.sig.none": "— none —",
  "pnl.event.sig.atlasEvents": "Events atlas emits",
  "pnl.event.sig.deployed": "Signals deployed models throw",
  "pnl.event.sig.new": "＋ New signal…",
  "pnl.event.eventsLink": "Events ↗",
  "pnl.event.sig.noReceiver": "No deployed process receives it: a signal is not buffered, so every throw is lost until one is deployed.",
  "pnl.event.sig.receivedBy.one": "Received by {n} deployed process: {processes}.",
  "pnl.event.sig.receivedBy.other": "Received by {n} deployed processes: {processes}.",
  "pnl.event.sig.atlasOwn": "{name} is a name atlas emits: a model that throws it speaks for atlas. Use a name of your own.",
  "pnl.event.sig.atlasReserved": "{name} is a name atlas emits (or reserves): a model that throws it speaks for atlas. Use a name of your own.",
  "pnl.event.sig.noSuchEvent": "atlas emits no event named {name}; this element would wait for something that never comes.",
  "pnl.event.sig.personal": "The listener receives personal data: {fields}. Only an administrator may deploy a model that listens to it.",
  "pnl.event.sig.namePh": "signal name",
  "pnl.event.sig.delete": "Delete signal",
  "pnl.event.sig.empty": "No signals yet — add one, then reference it from a signal throw/catch/boundary/start event.",
  "pnl.event.sig.addTitle": "Add a signal",
  "pnl.event.sig.add": "＋ Add signal",
  "pnl.event.sig.about": "A signal is a broadcast by name: a <b>throw</b> reaches every <b>catch</b>, boundary, event subprocess, and start event using the same signal — with no correlation key.",
  "pnl.event.err.code": "Error code",
  "pnl.event.err.shared": "Shared with every event that uses this error — a thrown code is caught by the nearest enclosing error boundary or error event subprocess with the same code (an empty code is a catch-all).",
  "pnl.event.err.label": "Error",
  "pnl.event.err.none": "— none —",
  "pnl.event.err.new": "＋ New error…",
  "pnl.event.err.codePh": "error code",
  "pnl.event.err.delete": "Delete error",
  "pnl.event.err.empty": "No errors yet — add one, then reference it from an error end event or error boundary.",
  "pnl.event.err.addTitle": "Add an error",
  "pnl.event.err.add": "＋ Add error",
  "pnl.event.err.about": "An error is a scoped failure caught by code: an <b>error end event</b> (or a worker) throws it, and the nearest enclosing <b>error boundary</b> or <b>error event subprocess</b> with the same code catches it — always interrupting.",
  "pnl.event.link.name": "Link name",
  "pnl.event.cond.expression": "Expression",
  "pnl.event.esc.code": "Escalation code",
  "pnl.event.esc.shared": "Shared with every event that uses this escalation — a raised code is caught by the nearest enclosing escalation boundary or escalation event subprocess with the same code (an empty code is a catch-all).",
  "pnl.event.esc.label": "Escalation",
  "pnl.event.esc.none": "— none —",
  "pnl.event.esc.new": "＋ New escalation…",
  "pnl.event.esc.codePh": "escalation code",
  "pnl.event.esc.delete": "Delete escalation",
  "pnl.event.esc.empty": "No escalations yet — add one, then reference it from an escalation throw/end event or escalation boundary.",
  "pnl.event.esc.addTitle": "Add an escalation",
  "pnl.event.esc.add": "＋ Add escalation",
  "pnl.event.esc.about": "An escalation is a matter raised up the scope chain: an <b>escalation throw</b> or <b>end event</b> raises it, and the nearest enclosing <b>escalation boundary</b> or <b>escalation event subprocess</b> with the same code catches it. Unlike an error, a catch may be <b>non-interrupting</b> (the activity keeps running) and an uncaught escalation is harmless.",
  "pnl.event.sv.fallbackValue": "Fallback value",
  "pnl.event.sv.value": "Value",
