  "pnl.main.nonInterrupting": "Non-interrupting — run alongside",
  "pnl.main.invalidId": "invalid id — must be unique and a valid identifier",
  "pnl.main.invalidProcessId": "invalid process id",
  "pnl.main.addVariable": "+ Add variable",
  "pnl.main.addVariableTitle": "Add a variable",
  "pnl.main.addConstant": "+ Add constant",
  "pnl.main.addConstantTitle": "Add a constant",
  "pnl.main.constantsHint": "Values every instance starts with and nobody is asked for: set on every start path, before the start variables, and read by expressions, scripts and Worker Types like any variable. Nothing in the run can replace one; only an operator's correction can. Its name is written in capitals (TENANT_ID). Set its source to <b>application</b> or <b>server</b> and it is read as <code>application.NAME</code> or <code>server.NAME</code>, taking what the application — or the installation, for every application — holds on each installation (the application's Constants tab, Admin → Engine → Server constants), with the value here as an optional fallback. A constant is in the model and in every instance, so it is no place for a secret.",
  "pnl.main.procDocPlaceholder": "What this process achieves, who it serves, when it runs…",
