  "pnl.main.class.open": "Open ↗",
  "pnl.main.pool.addFailed": "could not add a process to this pool",
  "pnl.main.head.pool": "Pool",
  "pnl.main.head.poolUnnamed": "(pool)",
  "pnl.main.pool.id": "Pool ID",
  "pnl.main.pool.docPlaceholder": "Who this participant is, what they are responsible for…",
  "pnl.main.pool.noProcess": "A pool is a <b>participant</b> — it doesn't hold the flow itself, it <i>executes a process</i>. This pool has <b>no process</b>, so it can't contain elements or run.",
  "pnl.main.pool.addProcessHint": "Add the process that sits between the pool and its elements — the participant runs it, and the elements you draw live inside it.",
  "pnl.main.pool.addProcessTitle": "Add a process to this collaboration",
  "pnl.main.pool.addProcess": "+ Add a process",
  "pnl.main.pool.startVarsHint": "Declared on this pool's process, these render as a typed form on <b>Deploy &amp; run</b> — with defaults and required checks. With a start form, the ones the form does not ask for are asked beneath it. The engine ignores the declaration; it's authoring metadata, so an instance started through the API gets no default. A value nobody enters is a constant, below.",
  "pnl.main.pool.hint": "The pool is a <b>participant</b> that executes the process below. The elements live in that process — the pool only labels who runs it.",
  "pnl.main.pool.procName": "Process name",
  "pnl.main.pool.procIdHint": "Each pool deploys as its own process; the <b>Process ID</b> is that deployment's identity — instances group by it, and renaming it deploys a new process rather than a new version. The <i>first</i> pool's process id is also what this draft is stored under, so renaming that one moves the draft on the next Save.",
  "pnl.main.pool.twoDocs": "Two descriptions, two subjects: the one above documents the <b>pool</b> (the participant), this one the <b>process</b> it executes. Every element inside takes its own.",
  "pnl.main.head.process": "Process",
  "pnl.main.head.processUnnamed": "(process)",
  "pnl.main.proc.startVarsHint": "Declared here, these render as a typed form on <b>Deploy &amp; run</b> — with defaults and required checks — instead of raw JSON. With a start form on the start event, the ones the form does not ask for are asked beneath it, on Deploy &amp; run, Start instance and the Tasks app's Start. The engine ignores the declaration; it's authoring metadata, so an instance started through the API or a public link gets no default. A value nobody enters is a constant, below.",
  "pnl.main.proc.idHint": "The Process ID is the identity deployments and instances are grouped by, and it is also what this draft is stored under &mdash; so <b>renaming it moves the draft</b> to the new id on the next Save rather than leaving a copy behind at the old one. An id another draft already holds is refused, never overwritten. Renaming it and deploying creates a new process rather than a new version.",
  "pnl.main.proc.docHint": "The <b>Documentation</b> is the process's own description — the place for the summary a reader needs before following the diagram. Every element takes one too; select it to write its part.",
  "pnl.main.proc.versionTag": "Version tag",
  "pnl.main.proc.executable": "Executable",
  "pnl.main.proc.execHint": "An <b>executable</b> process can be started and offered in the start lists; leave it off for a descriptive-only diagram. <b>Version tag</b> is an optional label for this revision.",
  "pnl.main.proc.ttl": "Instance TTL",
  "pnl.main.proc.ttlHint": "A self-cleaning <b>time-to-live</b> for instances of this process, as an ISO-8601 duration (e.g. <code>P7D</code> = 7 days, <code>PT12H</code> = 12 hours, <code>PT30M</code> = 30 minutes). An instance that outlives its TTL is automatically terminated and moved to history — where it stays queryable and can still be exported. It bounds how long an instance may <i>run</i>, not how long its record is kept; <b>History TTL</b> below decides that. Leave empty for no TTL (instances live until they complete or are cancelled). Set it above the longest run you legitimately expect.",
  "pnl.main.proc.historyTtl": "History TTL",
  "pnl.main.proc.historyTtlHint": "How long a <b>finished</b> instance of this process is kept before it is deleted for good, as an ISO-8601 duration (e.g. <code>P30D</code> = 30 days). Completed and terminated instances stay listed, queryable and exportable until it elapses; then retention removes the instance and everything it carried — variables, step history, decisions. Leave empty to fall back to the server-wide retention age, if the operator configured one. The delete is permanent and only ever happens once the instance's events are safely exported.",
  "pnl.main.proc.searchable": "Searchable variables",
  "pnl.main.proc.searchHint": "The variable names this process wants to be <b>found by</b>, comma-separated. A declared name is answered from a value index, so searching <code>identityId=MT-1998</code> over this version in Operations costs the number of matches instead of a read through every instance &mdash; and a trailing <code>*</code> asks for a prefix. Indexed is a variable at the instance's <b>top level</b> whose value is text, a number or true/false and stays under 256 bytes; a JSON structure or a variable local to one activity is not. A declared name is matched <b>exactly</b>, upper and lower case included, while an undeclared one keeps the read-through search it always had. Declaring nothing costs nothing, so name the one or two business keys you actually search by &mdash; a status that thousands of instances share is a poor declaration. It applies to instances started after the next deploy.",
  "pnl.main.proc.personal": "Personal variables",
  "pnl.main.proc.subject": "Data subject variable",
  "pnl.main.proc.personalHint": "The variables that hold <b>personal data</b>, comma-separated, and the one variable holding the <b>id of the person</b> they are about. A declared name is enciphered under a key belonging to that person before it ever reaches the engine, and erasing the person destroys that one key &mdash; which makes every copy of every value unreadable at once, including the backups nobody can reach any more. The price is that the engine can no longer read the value: a declared variable may be written, carried and handed to a worker, but it may <b>not appear in any expression</b> the engine evaluates &mdash; no gateway or flow condition, no input/output mapping, no script. Build what you need from it inside the worker that needs the result, where the plaintext exists for one call. The deploy refuses a model that breaks this, and refuses the two declarations apart: personal data with no subject could never be erased, and a subject with nothing personal enciphers nothing.",
  "pnl.main.proc.ttlInvalid": "Instance TTL must be a positive ISO-8601 duration, e.g. P7D or PT12H",
  "pnl.main.proc.historyTtlInvalid": "History TTL must be a positive ISO-8601 duration, e.g. P30D or PT12H",
  "pnl.main.head.collaboration": "Collaboration",
  "pnl.main.head.collaborationUnnamed": "(collaboration)",
  "pnl.main.collab.hint": "This diagram has several <b>pools</b>. A pool is a <b>participant</b> that <i>executes a process</i> — the process holds the flow, the pool just names who runs it, and each deploys as its own process. Select a pool to name it and configure the process it runs, or an element inside a pool to configure it. Pools talk to each other through <b>message events</b>: a throw event in one pool and a catch event in another that reference the <b>same message</b> below.",
  "pnl.main.collab.docPlaceholder": "What this collaboration is about, who the participants are…",
  "pnl.main.collab.docHint": "The <b>Documentation</b> describes the collaboration as a whole; each pool and each element inside it takes its own.",
  "pnl.main.head.unnamed": "(unnamed)",
