  "pnl.main.gen.docUserTask": "What the assignee has to check, decide or attach…",
  "pnl.main.gen.docFlow": "When this path is taken, and why…",
  "pnl.main.gen.docStep": "What this step is for, when it applies, who owns it…",
  "pnl.main.gen.docHint": "The <b>Documentation</b> is prose about this element — what it is for, the rule behind it, who owns it. The engine never acts on it, but it is part of the model, so it travels with every deploy, export and version.",
  "pnl.main.gen.docHintUserTask": "On a <b>user task</b> it is more than a note: the Tasks app shows it to the assignee as the <b>work instruction</b>, above the form — so write it to the person who will do the work.",
  "pnl.main.do.pointsTo": "Points to",
  "pnl.main.do.pointsToHint": "Point this box at an existing data object to show <b>the same object in several places</b> — one logical object, so you can put it next to each activity without long arrows across the diagram.",
  "pnl.main.do.class": "Class",
  "pnl.main.do.classWhat": "what this datum is",
  "pnl.main.do.className": "Class name",
  "pnl.main.do.noApplication": "This diagram is not filed under an application, so there is no information model to resolve a class against — and nothing here can be checked, which is why the Problems panel is empty rather than clean. Open this process's <b>draft</b> from its application, or deploy it from there, and the classes it models are offered here.",
  "pnl.main.do.nothingModelled": "This application models no data yet, so there is no class to point at. Draw one under <b>Data › Model</b> and it is offered here.",
  "pnl.main.do.openData": "Open Data ↗",
  "pnl.main.do.unresolved": "No class called <b>{name}</b> is modelled in this application yet — the Problems panel lists it, and a deploy is not refused for it.",
  "pnl.main.do.modelNow": "+ Model it now",
  "pnl.main.do.dataState": "Data state",
  "pnl.main.do.statesTitle": "The states {name} declares",
  "pnl.main.do.stateStart": "start",
  "pnl.main.do.stateFinal": "final",
  "pnl.main.do.notState": "not a state of {name}",
  "pnl.main.do.otherState": "Another state, not declared yet…",
  "pnl.main.do.stateName": "State name",
  "pnl.main.do.statesHint": "These are the states <b>{name}</b> declares in its lifecycle — <a href=\"{href}\" target=\"_blank\" rel=\"noopener\">open it ↗</a> to add one.",
  "pnl.main.do.collection": "Collection (a list of items)",
  "pnl.main.do.hint": "The <b>Class</b> is what this datum is, from the application's information model under <b>Data</b> — BPMN's <code>itemSubjectRef</code>. It is what lets two processes agree that their <code>order</code> is the same kind of thing, and what a write to a member of this object is checked against. A data object carries a value <i>and</i> a <b>data state</b> — <code>order [received]</code> → <code>[approved]</code>. The state set here is where the object starts each instance; a <b>data output association</b> (an arrow from an activity to this object) advances it and writes its value, a <b>data input association</b> reads it back, and the full state history is recorded per instance and survives restart. The <b>Name</b> is how the engine identifies it.",
  "pnl.main.dw.hint": "When the activity completes it writes <b>{name}</b>: each write's <b>FEEL value</b> (over the instance's variables) goes into its <b>Target member</b>, and the object's data state advances to the one on the target reference. Leave <b>Target member</b> empty to write the whole object; set it (e.g. <code>name</code>) to update just that field and keep the rest. Several writes are applied <b>in order</b> and recorded as <b>one</b> change to the object, so one activity that fills in a whole record is one arrow and not one arrow per field.",
  "pnl.main.dw.membersHint": "The members offered are the ones <b>{name}</b> declares — <a href=\"{href}\" target=\"_blank\" rel=\"noopener\">open it ↗</a> to add one. They say what this object is <i>shaped</i> like, which is a different thing from what a <b>FEEL value</b> above can read: that expression sees the instance's <b>variables</b>, and a data object is not one of them.",
  "pnl.main.dr.target": "Target variable",
  "pnl.main.dr.transform": "Transform",
  "pnl.main.dr.hint": "At activation this reads <b>{name}</b> into the <b>Target variable</b>, so the activity's FEEL can use it. Leave <b>Transform</b> empty to copy the object's value; set it (the object is available under its name) to compute the value written into the variable.",
  "pnl.main.rt.hint": "The receive task waits until this message is published (or thrown) with a matching correlation key, then continues. Attach a timer boundary event for a wait-or-time-out.",
  "pnl.main.task.type": "Task type",
